def confidence_message(p):
    if p >= 0.9:
        return "Very confident"
    elif p >= 0.7:
        return "Fairly confident"
    elif p >= 0.5:
        return "Leaning yes"
    else:
        return "Leaning no"

print(confidence_message(0.94))   # Very confident
print(confidence_message(0.65))   # Leaning yes
